import pytest
from hypothesis import given, assume
import hypothesis.strategies as st

from solution import get_max_triples


def reference(n: int) -> int:
    a = [i * i - i + 1 for i in range(1, n + 1)]
    count = 0
    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                if (a[i] + a[j] + a[k]) % 3 == 0:
                    count += 1
    return count


def comb3(m: int) -> int:
    if m < 3:
        return 0
    return m * (m - 1) * (m - 2) // 6


def expected_via_residues(n: int) -> int:
    cnt0 = sum(1 for i in range(1, n + 1) if (i * i - i + 1) % 3 == 0)
    cnt1 = sum(1 for i in range(1, n + 1) if (i * i - i + 1) % 3 == 1)
    cnt2 = sum(1 for i in range(1, n + 1) if (i * i - i + 1) % 3 == 2)
    assert cnt2 == 0
    assert cnt0 + cnt1 == n
    return comb3(cnt0) + comb3(cnt1)


# ---- concrete examples from spec ----

def test_example_n5_equals_1():
    assert get_max_triples(5) == 1


def test_example_array_explanation():
    # a = [1, 3, 7, 13, 21], only (1,7,13) sums to multiple of 3
    a = [i * i - i + 1 for i in range(1, 6)]
    assert a == [1, 3, 7, 13, 21]
    assert (1 + 7 + 13) % 3 == 0
    assert get_max_triples(5) == reference(5) == 1


# ---- boundaries: n < 3 has no triples ----

def test_n1_is_zero_and_int():
    r = get_max_triples(1)
    assert r == 0
    assert type(r) is int


def test_n2_is_zero_and_int():
    r = get_max_triples(2)
    assert r == 0
    assert type(r) is int


def test_n3_matches_brute_force():
    assert get_max_triples(3) == reference(3) == 0


def test_small_n_exhaustive_table():
    # brute-forced expected values for n=1..10
    expected = {n: reference(n) for n in range(1, 11)}
    for n, e in expected.items():
        r = get_max_triples(n)
        assert r == e, f"n={n}: got {r!r}, expected {e}"
        assert type(r) is int


# ---- properties ----

@given(st.integers(min_value=1, max_value=60))
def test_matches_brute_force_reference(n):
    assert get_max_triples(n) == reference(n)


@given(st.integers(min_value=1, max_value=1000))
def test_matches_residue_combinatorial_model(n):
    assert get_max_triples(n) == expected_via_residues(n)


@given(st.integers(min_value=1, max_value=1000))
def test_result_is_int_not_bool(n):
    r = get_max_triples(n)
    assert type(r) is int


@given(st.integers(min_value=1, max_value=500))
def test_result_nonnegative_and_bounded_by_total_triples(n):
    r = get_max_triples(n)
    assert r >= 0
    assert r <= comb3(n)


@given(st.integers(min_value=1, max_value=500))
def test_monotone_non_decreasing(n):
    # adding an element cannot remove existing triples
    assert get_max_triples(n + 1) >= get_max_triples(n)


@given(st.integers(min_value=1, max_value=500))
def test_residues_only_zero_and_one(n):
    # spec array never has residue 2 mod 3, so count must equal C(cnt0,3)+C(cnt1,3)
    cnt0 = sum(1 for i in range(1, n + 1) if (i * i - i + 1) % 3 == 0)
    cnt1 = n - cnt0
    assert get_max_triples(n) == comb3(cnt0) + comb3(cnt1)


def test_increment_consistency():
    # adding a[n+1] adds exactly the new triples ending at n+1
    for n in range(1, 30):
        a = [i * i - i + 1 for i in range(1, n + 2)]
        new_val = a[-1]
        added = 0
        for i in range(n):
            for j in range(i + 1, n):
                if (a[i] + a[j] + new_val) % 3 == 0:
                    added += 1
        assert get_max_triples(n + 1) == get_max_triples(n) + added
